/**
 * Bible Book 62: 1 யோவான் (1 John)
 */
if (typeof window.registerBibleBook === 'function') {
  window.registerBibleBook(62, {"id": 62, "testament": "NT", "code": "1JN", "name_en": "1 John", "name_ta": "1 யோவான்", "category": "General Epistles", "category_ta": "பொதுவான நிருபங்கள்", "total_chapters": 5, "chapters": {"1": {"chapter": 1, "duration": 128.01, "audio_url": "audio_nt/B23_01.mp3", "total_verses": 10, "verses": [{"verse": 1, "start": 4.8, "end": 21.1, "ta": "ஆதிமுதலாய் இருந்ததும், நாங்கள் கேட்டதும், எங்கள் கண்களினாலே கண்டதும், நாங்கள் நோக்கிப்பார்த்ததும், எங்கள் கைகளினாலே தொட்டுப்பார்த்ததுமாயிருக்கிற ஜீவவார்த்தையைக் குறித்து உங்களுக்கு அறிவிக்கிறோம்.", "en": "That which was from the beginning, which we have heard, which we have seen with our eyes, which we have looked upon, and our hands have handled, of the Word of life;"}, {"verse": 2, "start": 21.1, "end": 36.87, "ta": "அந்த ஜீவன் வெளிப்பட்டது; பிதாவினிடத்திலிருந்தும், எங்களுக்கு வெளிப்பட்டதுமான நித்தߠίமாயிருக்கிற அந்த ஜீவனை நாங்கள் கண்டு, அதைக்குறித்துச் சாட்சிக்கொடுத்து, அதை உங்களுக்கு அறிவிக்கிறோம்.", "en": "(For the life was manifested, and we have seen it , and bear witness, and shew unto you that eternal life, which was with the Father, and was manifested unto us;)"}, {"verse": 3, "start": 36.87, "end": 52.49, "ta": "நீங்களும் எங்களோடே ஐக்கியமுள்ளவர்களாகும்படி, நாங்கள் கண்டும் கேட்டும் இருக்கிறதை உங்களுக்கும் அறிவிக்கிறோம்; எங்களுடைய ஐக்கியம் பிதாவோடும் அவருடைய குமாரனாகிய இயேசுகிறிஸ்துவோடும் இருக்கிறது.", "en": "That which we have seen and heard declare we unto you, that ye also may have fellowship with us: and truly our fellowship is with the Father, and with his Son Jesus Christ."}, {"verse": 4, "start": 52.49, "end": 58.15, "ta": "உங்கள் சந்தோஷம் நிறைவாயிருக்கும்படி இவைகளை உங்களுக்கு எழுதுகிறேன்.", "en": "And these things write we unto you, that your joy may be full."}, {"verse": 5, "start": 58.15, "end": 69.39, "ta": "தேவன் ஒளியாயிருக்கிறார், அவரில் எவ்வளவேனும் இருளில்லை; இது நாங்கள் அவரிடத்தில் கேட்டு, உங்களுக்கு அறிவிக்கிற விசேஷமாயிருக்கிறது.", "en": "This then is the message which we have heard of him, and declare unto you, that God is light, and in him is no darkness at all."}, {"verse": 6, "start": 69.39, "end": 80.78, "ta": "நாம் அவரோடே ஐக்கியப்பட்டவர்கள் என்று சொல்லியும், இருளிலே நடக்கிறவர்களாயிருந்தால், சத்தியத்தின்படி நடவாமல் பொய்சொல்லுகிறவர்களாயிருப்போம்.", "en": "If we say that we have fellowship with him, and walk in darkness, we lie, and do not the truth:"}, {"verse": 7, "start": 80.78, "end": 95.72, "ta": "அவர் ஒளியிலிருக்கிறதுபோல நாமும் ஒளியிலே நடந்தால் ஒருவரோடொருவர் ஐக்கியப்பட்டிருப்போம்; அவருடைய குமாரனாகிய இயேசுகிறிஸ்துவின் இரத்தம் சகல பாவங்களையும் நீக்கி, நம்மைச் சுத்திகரிக்கும்.", "en": "But if we walk in the light, as he is in the light, we have fellowship one with another, and the blood of Jesus Christ his Son cleanseth us from all sin."}, {"verse": 8, "start": 95.72, "end": 103.72, "ta": "நமக்குப் பாவமில்லையென்போமானால் நம்மை நாமே வஞ்சிக்கிறவர்களாயிருப்போம், சத்தியம் நமக்குள் இராது.", "en": "If we say that we have no sin, we deceive ourselves, and the truth is not in us."}, {"verse": 9, "start": 103.72, "end": 117.0, "ta": "நம்முடைய பாவங்களை நாம் அறிக்கையிட்டால், பாவங்களை நமக்கு மன்னித்து எல்லா அநியாயத்தையும் நீக்கி நம்மைச் சுத்திகரிப்பதற்கு அவர் உண்மையும் நீதியும் உள்ளவராயிருக்கிறார்.", "en": "If we confess our sins, he is faithful and just to forgive us our sins, and to cleanse us from all unrighteousness."}, {"verse": 10, "start": 117.0, "end": 126.51, "ta": "நாம் பாவஞ்செய்யவில்லையென்போமானால், நாம் அவரைப் பொய்யராக்குகிறவர்களாயிருப்போம், அவருடைய வார்த்தை நமக்குள் இராது.", "en": "If we say that we have not sinned, we make him a liar, and his word is not in us."}]}, "2": {"chapter": 2, "duration": 373.6, "audio_url": "audio_nt/B23_02.mp3", "total_verses": 29, "verses": [{"verse": 1, "start": 3.8, "end": 20.14, "ta": "என் பிள்ளைகளே, நீங்கள் பாவஞ்செய்யாதபடிக்கு இவைகளை உங்களுக்கு எழுதுகிறேன்; ஒருவன் பாவஞ்செய்வானானால் நீதிபரராயிருக்கிற இயேசுகிறிஸ்து நமக்காகப் பிதாவினிடத்தில் பரிந்து பேசுகிறவராயிருக்கிறார்.", "en": "My little children, these things write I unto you, that ye sin not. And if any man sin, we have an advocate with the Father, Jesus Christ the righteous:"}, {"verse": 2, "start": 20.14, "end": 33.71, "ta": "நம்முடைய பாவங்களை நிவிர்த்தி செய்கிற கிருபாதாரபலி அவரே; நம்முடைய பாவங்களை மாத்திரம் அல்ல, சர்வலோகத்தின் பாவங்களையும் நிவிர்த்திசெய்கிற பலியாயிருக்கிறார்.", "en": "And he is the propitiation for our sins: and not for ours only, but also for the sins of the whole world."}, {"verse": 3, "start": 33.71, "end": 41.95, "ta": "அவருடைய கற்பனைகளை நாம் கைக்கொள்ளுகிறவர்களானால், அவரை அறிந்திருக்கிறோமென்பதை அதினால் அறிவோம்.", "en": "And hereby we do know that we know him, if we keep his commandments."}, {"verse": 4, "start": 41.95, "end": 52.58, "ta": "அவரை அறிந்திருக்கிறேனென்று சொல்லியும், அவருடைய கற்பனைகளைக் கைக்கொள்ளாதவன் பொய்யனாயிருக்கிறான், அவனுக்குள் சத்தியமில்லை.", "en": "He that saith, I know him, and keepeth not his commandments, is a liar, and the truth is not in him."}, {"verse": 5, "start": 52.58, "end": 65.04, "ta": "அவருடைய வசனத்தைக் கைக்கொள்ளுகிறவனிடத்தில் தேவ அன்பு மெய்யாகப் பூரணப்பட்டிருக்கும்; நாம் அவருக்குள் இருக்கிறோமென்பதை அதினாலே அறிந்திருக்கிறோம்.", "en": "But whoso keepeth his word, in him verily is the love of God perfected: hereby know we that we are in him."}, {"verse": 6, "start": 65.04, "end": 72.73, "ta": "அவருக்குள் நிலைத்திருக்கிறேனென்று சொல்லுகிறவன், அவர் நடந்தபடியே தானும் நடக்கவேண்டும்.", "en": "He that saith he abideth in him ought himself also so to walk, even as he walked."}, {"verse": 7, "start": 72.73, "end": 87.72, "ta": "சகோதரரே, நான் உங்களுக்குப் புதிய கற்பனையை அல்ல, ஆதிமுதல் நீங்கள் பெற்றிருக்கிற பழைய கற்பனையையே எழுதுகிறேன்; அந்தப் பழைய கற்பனை நீங்கள் ஆதிமுதல் கேட்டிருக்கிற வசனந்தானே.", "en": "Brethren, I write no new commandment unto you, but an old commandment which ye had from the beginning. The old commandment is the word which ye have heard from the beginning."}, {"verse": 8, "start": 87.72, "end": 104.3, "ta": "மேலும், நான் புதிய கற்பனையையும் உங்களுக்கு எழுதுகிறேன், இது அவருக்குள்ளும் உங்களுக்குள்ளும் மெய்யாயிருக்கிறது; ஏனென்றால், இருள் நீங்கிப்போகிறது, மெய்யான ஒளி இப்பொழுது பிரகாசிக்கிறது.", "en": "Again, a new commandment I write unto you, which thing is true in him and in you: because the darkness is past, and the true light now shineth."}, {"verse": 9, "start": 104.3, "end": 112.63, "ta": "ஒளியிலே இருக்கிறேன் என்று சொல்லியும் தன் சகோதரனைப் பகைக்கிறவன் இதுவரைக்கும் இருளிலே இருக்கிறான்.", "en": "He that saith he is in the light, and hateth his brother, is in darkness even until now."}, {"verse": 10, "start": 112.63, "end": 121.36, "ta": "தன் சகோதரனிடத்தில் அன்புகூருகிறவன் ஒளியிலே நிலைகொண்டிருக்கிறான்; அவனிடத்தில் இடறல் ஒன்றுமில்லை.", "en": "He that loveth his brother abideth in the light, and there is none occasion of stumbling in him."}, {"verse": 11, "start": 121.36, "end": 134.45, "ta": "தன் சகோதரனைப் பகைக்கிறவன் இருளிலே இருந்து இருளிலே நடக்கிறான்; இருளானது அவன் கண்களைக் குருடாக்கினபடியால் தான் போகும் இடம் இன்னதென்று அறியாதிருக்கிறான்.", "en": "But he that hateth his brother is in darkness, and walketh in darkness, and knoweth not whither he goeth, because that darkness hath blinded his eyes."}, {"verse": 12, "start": 134.45, "end": 143.65, "ta": "பிள்ளைகளே, அவருடைய நாமத்தினிமித்தம் உங்கள் பாவங்கள் மன்னிக்கப்பட்டிருக்கிறதினால் உங்களுக்கு எழுதுகிறேன்.", "en": "I write unto you, little children, because your sins are forgiven you for his name’s sake."}, {"verse": 13, "start": 143.65, "end": 162.05, "ta": "பிதாக்களே, ஆதிமுதலிருக்கிறவரை நீங்கள் அறிந்திருக்கிறதினால் உங்களுக்கு எழுதுகிறேன். வாலிபரே, ஜெயித்ததினால் உங்களுக்கு எழுதுகிறேன். பிள்ளைகளே நீங்கள் பிதாவை அறிந்திருக்கிறதினால் உங்களுக்கு எழுதுகிறேன்.", "en": "I write unto you, fathers, because ye have known him that is from the beginning. I write unto you, young men, because ye have overcome the wicked one. I write unto you, little children, because ye have known the Father."}, {"verse": 14, "start": 162.05, "end": 183.94, "ta": "பிதாக்களே, ஆதிமுதலிருக்கிறவரை நீங்கள் அறிந்திருக்கிறதினால் உங்களுக்கு எழுதியிருக்கிறேன். வாலிபரே, நீங்கள் பலவான்களாயிருக்கிறதினாலும், தேவவசனம் உங்களில் நிலைத்திருக்கிறதினாலும், நீங்கள் பொல்லாங்கனை ஜெயித்ததினாலும், உங்களுக்கு எழுதியிருக்கிறேன்.", "en": "I have written unto you, fathers, because ye have known him that is from the beginning. I have written unto you, young men, because ye are strong, and the word of God abideth in you, and ye have overcome the wicked one."}, {"verse": 15, "start": 183.94, "end": 194.49, "ta": "உலகத்திலும் உலகத்திலுள்ளவைகளிலும் அன்புகூராதிருங்கள்; ஒருவன் உலகத்தில் அன்புகூர்ந்தால் அவனிடத்தில் பிதாவின் அன்பில்லை.", "en": "Love not the world, neither the things that are in the world. If any man love the world, the love of the Father is not in him."}, {"verse": 16, "start": 194.49, "end": 208.38, "ta": "ஏனெனில், மாம்சத்தின் இச்சையும், கண்களின் இச்சையும், ஜீவனத்தின் பெருமையுமாகிய உலகத்திலுள்ளவைகளெல்லாம் பிதாவினாலுண்டானவைகளல்ல, அவைகள் உலகத்தினாலுண்டானவைகள்.", "en": "For all that is in the world, the lust of the flesh, and the lust of the eyes, and the pride of life, is not of the Father, but is of the world."}, {"verse": 17, "start": 208.38, "end": 217.89, "ta": "உலகமும் அதின் இச்சையும் ஒழிந்துபோம்; தேவனுடைய சித்தத்தின்படி செய்கிறவனோ என்றென்றைக்கும் நிலைத்திருப்பான்.", "en": "And the world passeth away, and the lust thereof: but he that doeth the will of God abideth for ever."}, {"verse": 18, "start": 217.89, "end": 234.47, "ta": "பிள்ளைகளே, இது கடைசிக்காலமாயிருக்கிறது; அந்திக்கிறிஸ்து வருகிறானென்று நீங்கள் கேள்விப்பட்டபடி இப்பொழுதும் அநேக அந்திக்கிறிஸ்துகள் இருக்கிறார்கள்; அதினாலே இது கடைசிக்காலமென்று அறிகிறோம்.", "en": "Little children, it is the last time: and as ye have heard that antichrist shall come, even now are there many antichrists; whereby we know that it is the last time."}, {"verse": 19, "start": 234.47, "end": 253.67, "ta": "அவர்கள் நம்மைவிட்டுப் பிரிந்து போனார்கள், ஆகிலும் அவர்கள் நம்முடையவர்களாயிருக்கவில்லை; நம்முடையவர்களாயிருந்தார்களானால் நம்முடனே நிலைத்திருப்பார்களே; எல்லாரும் நம்முடையவர்களல்லவென்று வெளியாகும்படிக்கே பிரிந்துபோனார்கள்.", "en": "They went out from us, but they were not of us; for if they had been of us, they would no doubt have continued with us: but they went out , that they might be made manifest that they were not all of us."}, {"verse": 20, "start": 253.67, "end": 260.09, "ta": "நீங்கள் பரிசுத்தராலே அபிஷேகம் பெற்றுச் சகலத்தையும் அறிந்திருக்கிறீர்கள்.", "en": "But ye have an unction from the Holy One, and ye know all things."}, {"verse": 21, "start": 260.09, "end": 275.64, "ta": "சத்தியத்தை நீங்கள் அறியாததினாலல்ல, நீங்கள் சத்தியத்தை அறிந்திருக்கிறதினாலும் சத்தியத்தினால் ஒரு பொய்யுமுண்டாயிராதென்பதை நீங்கள் அறிந்திருக்கிறதினாலும், உங்களுக்கு எழுதியிருக்கிறேன்.", "en": "I have not written unto you because ye know not the truth, but because ye know it, and that no lie is of the truth."}, {"verse": 22, "start": 275.64, "end": 287.06, "ta": "இயேசுவைக் கிறிஸ்து அல்ல என்று மறுதலிக்கிறவனேயல்லாமல் வேறே யார் பொய்யன்? பிதாவையும் குமாரனையும் மறுதலிக்கிறவனே அந்திக்கிறிஸ்து.", "en": "Who is a liar but he that denieth that Jesus is the Christ? He is antichrist, that denieth the Father and the Son."}, {"verse": 23, "start": 287.06, "end": 295.79, "ta": "குமாரனை மறுதலிக்கிறவன் பிதாவை உடையவனல்ல, குமாரனை அறிக்கையிடுகிறவன் பிதாவையும் உடையவனாயிருக்கிறான்.", "en": "Whosoever denieth the Son, the same hath not the Father: (but) he that acknowledgeth the Son hath the Father also ."}, {"verse": 24, "start": 295.79, "end": 311.73, "ta": "ஆகையால் ஆதிமுதல் நீங்கள் கேள்விப்பட்டது உங்களில் நிலைத்திருக்கக்கடவது; ஆதிமுதல் நீங்கள் கேள்விப்பட்டது உங்களில் நிலைத்திருந்தால், நீங்களும் குமாரனிலும் பிதாவிலும் நிலைத்திருப்பீர்கள்.", "en": "Let that therefore abide in you, which ye have heard from the beginning. If that which ye have heard from the beginning shall remain in you, ye also shall continue in the Son, and in the Father."}, {"verse": 25, "start": 311.73, "end": 317.68, "ta": "நித்திய ஜீவனை அளிப்பேன் என்பதே அவர் நமக்குச் செய்த வாக்குத்தத்தம்.", "en": "And this is the promise that he hath promised us, even eternal life."}, {"verse": 26, "start": 317.68, "end": 324.03, "ta": "உங்களை வஞ்சிக்கிறவர்களைக் குறித்து இவைகளை உங்களுக்கு எழுதியிருக்கிறேன்.", "en": "These things have I written unto you concerning them that seduce you."}, {"verse": 27, "start": 324.03, "end": 346.64, "ta": "நீங்கள் அவராலே பெற்ற அபிஷேகம் உங்களில் நிலைத்திருக்கிறது, ஒருவரும் உங்களுக்குப் போதிக்கவேண்டுவதில்லை; அந்த அபிஷேகம் சகலத்தையுங்குறித்து உங்களுக்குப் போதிக்கிறது; அது சத்தியமாயிருக்கிறது, பொய்யல்ல, அது உங்களுக்குப் போதித்தபடியே அவரில் நிலைத்திருப்பீர்களாக.", "en": "But the anointing which ye have received of him abideth in you, and ye need not that any man teach you: but as the same anointing teacheth you of all things, and is truth, and is no lie, and even as it hath taught you, ye shall abide in him."}, {"verse": 28, "start": 346.64, "end": 360.44, "ta": "இப்படியிருக்க, பிள்ளைகளே, அவர் வெளிப்படும்போது நாம் அவர் வருகையில் அவருக்கு முன்பாக வெட்கப்பட்டுப்போகாமல் தைரியமுள்ளவர்களாயிருக்கும்படி அவரில் நிலைத்திருங்கள்.", "en": "And now, little children, abide in him; that, when he shall appear, we may have confidence, and not be ashamed before him at his coming."}, {"verse": 29, "start": 360.44, "end": 372.1, "ta": "அவர் நீதியுள்ளவராயிருக்கிறாரென்று உங்களுக்குத் தெரிந்திருப்பதினால், நீதியைச் செய்கிறவனெவனும் அவரில் பிறந்தவனென்று அறிந்திருக்கிறீர்கள்.", "en": "If ye know that he is righteous, ye know that every one that doeth righteousness is born of him."}]}, "3": {"chapter": 3, "duration": 277.56, "audio_url": "audio_nt/B23_03.mp3", "total_verses": 24, "verses": [{"verse": 1, "start": 3.8, "end": 16.69, "ta": "நாம் தேவனுடைய பிள்ளைகளென்று அழைக்கப்படுவதினாலே பிதாவானவர் நமக்குப் பாராட்டின அன்பு எவ்வளவு பெரிதென்று பாருங்கள்; உலகம் அவரை அறியாதபடியினாலே நம்மையும் அறியவில்லை.", "en": "Behold, what manner of love the Father hath bestowed upon us, that we should be called the sons of God: therefore the world knoweth us not, because it knew him not."}, {"verse": 2, "start": 16.69, "end": 35.73, "ta": "பிரியமானவர்களே, இப்பொழுது தேவனுடைய பிள்ளைகளாயிருக்கிறோம், இனி எவ்விதமாயிருப்போமென்று இன்னும் வெளிப்படவில்லை; ஆகிலும் அவர் வெளிப்படும்போது அவர் இருக்கிறவண்ணமாகவே நாம் அவரைத் தரிசிப்பதினால், அவருக்கு ஒப்பாயிருப்போமென்று அறிந்திருக்கிறோம்.", "en": "Beloved, now are we the sons of God, and it doth not yet appear what we shall be: but we know that, when he shall appear, we shall be like him; for we shall see him as he is."}, {"verse": 3, "start": 35.73, "end": 46.13, "ta": "அவர்மேல் இப்படிப்பட்ட நம்பிக்கை வைத்திருக்கிறவனெவனும், அவர் சுத்தமுள்ளவராயிருக்கிறதுபோல, தன்னையும் சுத்திகரித்துக்கொள்ளுகிறான்.", "en": "And every man that hath this hope in him purifieth himself, even as he is pure."}, {"verse": 4, "start": 46.13, "end": 53.38, "ta": "பாவஞ்செய்கிற எவனும் நியாயப்பிரமாணத்தை மீறுகிறான்; நியாயப்பிரமாணத்தை மீறுகிறதே பாவம்.", "en": "Whosoever committeth sin transgresseth also the law: for sin is the transgression of the law."}, {"verse": 5, "start": 53.38, "end": 61.28, "ta": "அவர் நம்முடைய பாவங்களைச் சுமந்து தீர்க்க வெளிப்பட்டாரென்று அறிவீர்கள்; அவரிடத்தில் பாவமில்லை.", "en": "And ye know that he was manifested to take away our sins; and in him is no sin."}, {"verse": 6, "start": 61.28, "end": 69.78, "ta": "அவரில் நிலைத்திருக்கிற எவனும் பாவஞ்செய்கிறதில்லை; பாவஞ்செய்கிற எவனும் அவரைக் காணவுமில்லை, அவரை அறியவுமில்லை", "en": "Whosoever abideth in him sinneth not: whosoever sinneth hath not seen him, neither known him."}, {"verse": 7, "start": 69.78, "end": 81.06, "ta": "பிள்ளைகளே நீங்கள் ஒருவராலும் வஞ்சிக்கப்படாதிருங்கள்; நீதியைச் செய்கிறவன் அவர் நீதியுள்ளவராயிருக்கிறதுபோலத் தானும் நீதியுள்ளவனாயிருக்கிறான்.", "en": "Little children, let no man deceive you: he that doeth righteousness is righteous, even as he is righteous."}, {"verse": 8, "start": 81.06, "end": 94.02, "ta": "பாவஞ்செய்கிறவன் பிசாசினாலுண்டாயிருக்கிறான்; ஏனெனில் பிசாசானவன் ஆதிமுதல் பாவஞ்செய்கிறான், பிசாசினுடைய கிரியைகளை அழிக்கும்படிக்கே தேவனுடைய குமாரன் வெளிப்பட்டார்.", "en": "He that committeth sin is of the devil; for the devil sinneth from the beginning. For this purpose the Son of God was manifested, that he might destroy the works of the devil."}, {"verse": 9, "start": 94.02, "end": 105.37, "ta": "தேவனால் பிறந்த எவனும் பாவஞ்செய்யான், ஏனெனில் அவருடைய வித்து அவனுக்குள் தரித்திருக்கிறது; அவன் தேவனால் பிறந்தபடியினால் பாவஞ்செய்யமாட்டான்.", "en": "Whosoever is born of God doth not commit sin; for his seed remaineth in him: and he cannot sin, because he is born of God."}, {"verse": 10, "start": 105.37, "end": 119.21, "ta": "இதினாலே தேவனுடைய பிள்ளைகள் இன்னாரென்றும், பிசாசின் பிள்ளைகள் இன்னாரென்றும் வெளிப்படும்; நீதியைச்செய்யாமலும் தன் சகோதரனில் அன்புகூராமலும் இருக்கிற எவனும் தேவனாலுண்டானவனல்ல.", "en": "In this the children of God are manifest, and the children of the devil: whosoever doeth not righteousness is not of God, neither he that loveth not his brother."}, {"verse": 11, "start": 119.21, "end": 126.46, "ta": "நாம் ஒருவரிலொருவர் அன்புகூரவேண்டுமென்பதே நீங்கள் ஆதிமுதல் கேள்விப்பட்ட விசேஷமாயிருக்கிறது.", "en": "For this is the message that ye heard from the beginning, that we should love one another."}, {"verse": 12, "start": 126.46, "end": 143.96, "ta": "பொல்லாங்கனால் உண்டாயிருந்து தன் சகோதரனைக் கொலைசெய்த காயீனைப்போலிருக்கவேண்டாம்; அவன் எதினிமித்தம் அவனைக் கொலைசெய்தான்? தன் கிரியைகள் பொல்லாதவைகளும், தன் சகோதரனுடைய கிரியைகள் நீதியுள்ளவைகளுமாயிருந்ததினிமித்தந்தானே.", "en": "Not as Cain, who was of that wicked one, and slew his brother. And wherefore slew he him? Because his own works were evil, and his brother’s righteous."}, {"verse": 13, "start": 143.96, "end": 149.23, "ta": "என் சகோதரரே, உலகம் உங்களைப் பகைத்தால் ஆச்சரியப்படாதிருங்கள்.", "en": "Marvel not, my brethren, if the world hate you."}, {"verse": 14, "start": 149.23, "end": 163.36, "ta": "நாம் சகோதரரிடத்தில் அன்புகூருகிறபடியால், மரணத்தைவிட்டு நீங்கி ஜீவனுக்குட்பட்டிருக்கிறோமென்று அறிந்திருக்கிறோம். சகோதரனிடத்தில் அன்புகூராதவன் மரணத்தில் நிலைகொண்டிருக்கிறான்.", "en": "We know that we have passed from death unto life, because we love the brethren. He that loveth not his brother abideth in death."}, {"verse": 15, "start": 163.36, "end": 174.05, "ta": "தன் சகோதரனைப் பகைக்கிற எவனும் மனுஷகொலைபாதகனாயிருக்கிறான்; மனுஷ கொலைபாதகனெவனோ அவனுக்குள் நித்தியஜீவன் நிலைத்திராது என்று அறிவீர்கள்.", "en": "Whosoever hateth his brother is a murderer: and ye know that no murderer hath eternal life abiding in him."}, {"verse": 16, "start": 174.05, "end": 185.33, "ta": "அவர் தம்முடைய ஜீவனை நமக்காகக் கொடுத்ததினாலே அன்பு இன்னதென்று அறிந்திருக்கிறோம்; நாமும் சகோதரருக்காக ஜீவனைக்கொடுக்கக் கடனாளிகளாயிருக்கிறோம்.", "en": "Hereby perceive we the love of God , because he laid down his life for us: and we ought to lay down our lives for the brethren."}, {"verse": 17, "start": 185.33, "end": 198.73, "ta": "ஒருவன் இவ்வுலக ஆஸ்தி உடையவனாயிருந்து, தன் சகோதரனுக்குக் குறைச்சலுண்டென்று கண்டு, தன் இருதயத்தை அவனுக்கு அடைத்துக்கொண்டால், அவனுக்குள் தேவ அன்பு நிலைகொள்ளுகிறதெப்படி?", "en": "But whoso hath this world’s good, and seeth his brother have need, and shutteth up his bowels of compassion from him, how dwelleth the love of God in him?"}, {"verse": 18, "start": 198.73, "end": 206.64, "ta": "என் பிள்ளைகளே, வசனத்தினாலும், நாவினாலுமல்ல, கிரியையினாலும் உண்மையினாலும் அன்புகூரக்கடவோம்.", "en": "My little children, let us not love in word, neither in tongue; but in deed and in truth."}, {"verse": 19, "start": 206.64, "end": 216.38, "ta": "இதினாலே நாம் நம்மைச் சத்தியத்திற்குரியவர்களென்று அறிந்து, நம்முடைய இருதயத்தை அவருக்கு முன்பாக நிச்சயப்படுத்திக்கொள்ளலாம்.", "en": "And hereby we know that we are of the truth, and shall assure our hearts before him."}, {"verse": 20, "start": 216.38, "end": 227.0, "ta": "நம்முடைய இருதயமே நம்மைக் குற்றவாளிகளாகத் தீர்க்குமானால், தேவன் நம்முடைய இருதயத்திலும் பெரியவராயிருந்து சகலத்தையும் அறிந்திருக்கிறார்.", "en": "For if our heart condemn us, God is greater than our heart, and knoweth all things."}, {"verse": 21, "start": 227.0, "end": 236.15, "ta": "பிரியமானவர்களே, நம்முடைய இருதயம் நம்மைக் குற்றவாளிகளென்று தீர்க்காதிருந்தால், நாம் தேவனிடத்தில் தைரியங்கொண்டிருந்து,", "en": "Beloved, if our heart condemn us not, then have we confidence toward God."}, {"verse": 22, "start": 236.15, "end": 247.57, "ta": "அவருடைய கற்பனைகளை நாம் கைக்கொண்டு அவருக்கு முன்பாகப் பிரியமானவைகளைச் செய்கிறபடியினால் நாம் வேண்டிக்கொள்ளுகிறதெதுவோ அதை அவராலே பெற்றுக்கொள்ளுகிறோம்.", "en": "And whatsoever we ask, we receive of him, because we keep his commandments, and do those things that are pleasing in his sight."}, {"verse": 23, "start": 247.57, "end": 261.05, "ta": "நாம் அவருடைய குமாரனாகிய இயேசுகிறிஸ்துவின் நாமத்தின்மேல் விசுவாசமாயிருந்து, அவர் நமக்குக் கட்டளையிட்டபடி ஒருவரிலொருவர் அன்பாயிருக்கவேண்டுமென்பதே அவருடைய கற்பனையாயிருக்கிறது.", "en": "And this is his commandment, That we should believe on the name of his Son Jesus Christ, and love one another, as he gave us commandment."}, {"verse": 24, "start": 261.05, "end": 276.06, "ta": "அவருடைய கட்டளைகளைக் கைக்கொள்ளுகிறவன் அவரில் நிலைத்திருக்கிறான். அவரும் அவனில் நிலைத்திருக்கிறார்; அவர் நம்மில் நிலைத்திருக்கிறதை அவர் நமக்குத் தந்தருளின ஆவியினாலே அறிந்திருக்கிறோம்.", "en": "And he that keepeth his commandments dwelleth in him, and he in him. And hereby we know that he abideth in us, by the Spirit which he hath given us."}]}, "4": {"chapter": 4, "duration": 252.86, "audio_url": "audio_nt/B23_04.mp3", "total_verses": 21, "verses": [{"verse": 1, "start": 3.8, "end": 15.79, "ta": "அநேகங் கள்ளத்தீர்க்கதரிசிகள் தோன்றியிருப்பதினால், நீங்கள் எல்லா ஆவிகளையும் நம்பாமல், அந்த ஆவிகள் தேவனாலுண்டானவைகளோ என்று சோதித்தறியுங்கள்.", "en": "Beloved, believe not every spirit, but try the spirits whether they are of God: because many false prophets are gone out into the world."}, {"verse": 2, "start": 15.79, "end": 26.52, "ta": "தேவஆவியை நீங்கள் எதினாலே அறியலாமென்றால்: மாம்சத்தில் வந்த இயேசுகிறிஸ்துவை அறிக்கைபண்ணுகிற எந்த ஆவியும் தேவனால் உண்டாயிருக்கிறது.", "en": "Hereby know ye the Spirit of God: Every spirit that confesseth that Jesus Christ is come in the flesh is of God:"}, {"verse": 3, "start": 26.52, "end": 42.19, "ta": "மாம்சத்தில் வந்த இயேசுகிறிஸ்துவை அறிக்கைபண்ணாத எந்த ஆவியும் தேவனால் உண்டானதல்ல; வருமென்று நீங்கள் கேள்விப்பட்ட அந்திக்கிறிஸ்துவினுடைய ஆவி அதுவே, அது இப்பொழுதும் உலகத்தில் இருக்கிறது.", "en": "And every spirit that confesseth not that Jesus Christ is come in the flesh is not of God: and this is that spirit of antichrist, whereof ye have heard that it should come; and even now already is it in the world."}, {"verse": 4, "start": 42.19, "end": 53.47, "ta": "பிள்ளைகளே, நீங்கள் தேவனாலுண்டாயிருந்து, அவர்களை ஜெயித்தீர்கள்; ஏனெனில் உலகத்திலிருக்கிறவனிலும் உங்களிலிருக்கிறவர் பெரியவர்.", "en": "Ye are of God, little children, and have overcome them: because greater is he that is in you, than he that is in the world."}, {"verse": 5, "start": 53.47, "end": 63.42, "ta": "அவர்கள் உலகத்துக்குரியவர்கள், ஆகையால் உலகத்துக்குரியவைகளைப் பேசுகிறார்கள், உலகமும் அவர்களுக்குச் செவிகொடுக்கும்.", "en": "They are of the world: therefore speak they of the world, and the world heareth them."}, {"verse": 6, "start": 63.42, "end": 81.91, "ta": "நாங்கள் தேவனால் உண்டானவர்கள்; தேவனை அறிந்தவன் எங்களுக்குச் செவிகொடுக்கிறான்; தேவனால் உண்டாயிராதவன் எங்களுக்குச் செவிகொடுக்கிறதில்லை; இதினாலே சத்திய ஆவி இன்னதென்றும், வஞ்சகஆவி இன்னதென்றும் அறிந்திருக்கிறோம்.", "en": "We are of God: he that knoweth God heareth us; he that is not of God heareth not us. Hereby know we the spirit of truth, and the spirit of error."}, {"verse": 7, "start": 81.91, "end": 93.03, "ta": "அன்பாயிருக்கக்கடவோம்; ஏனெனில் அன்பு தேவனால் உண்டாயிருக்கிறது; அன்புள்ள எவனும் தேவனால் பிறந்து, அவரை அறிந்திருக்கிறான்.", "en": "Beloved, let us love one another: for love is of God; and every one that loveth is born of God, and knoweth God."}, {"verse": 8, "start": 93.03, "end": 98.36, "ta": "அன்பில்லாதவன் தேவனை அறியான், தேவன் அன்பாகவே இருக்கிறார்.", "en": "He that loveth not knoweth not God; for God is love."}, {"verse": 9, "start": 98.36, "end": 109.33, "ta": "தம்முடைய ஒரே பேறான குமாரனாலே நாம் பிழைக்கும்படிக்கு தேவன் அவரை இவ்வுலகத்திலே அனுப்பினதினால் தேவன் நம்மேல் வைத்த அன்பு வெளிப்பட்டது.", "en": "In this was manifested the love of God toward us, because that God sent his only begotten Son into the world, that we might live through him."}, {"verse": 10, "start": 109.33, "end": 124.99, "ta": "நாம் தேவனிடத்தில் அன்புகூர்ந்ததினால் அல்ல, அவர் நம்மிடத்தில் அன்புகூர்ந்து, நம்முடைய பாவங்களை நிவிர்த்திசெய்கிற கிருபாதாரபலியாகத் தம்முடைய குமாரனை அனுப்பினதினாலே அன்பு உண்டாயிருக்கிறது.", "en": "Herein is love, not that we loved God, but that he loved us, and sent his Son to be the propitiation for our sins."}, {"verse": 11, "start": 124.99, "end": 136.12, "ta": "பிரியமானவர்களே, தேவன் இவ்விதமாய் நம்மிடத்தில் அன்புகூர்ந்திருக்க, நாமும் ஒருவரிடத்தில் ஒருவர் அன்புகூரக் கடனாளிகளாயிருக்கிறோம்.", "en": "Beloved, if God so loved us, we ought also to love one another."}, {"verse": 12, "start": 136.12, "end": 149.59, "ta": "தேவனை ஒருவரும் ஒருபோதும் கண்டதில்லை; நாம் ஒருவரிடத்தில் ஒருவர் அன்புகூர்ந்தால் தேவன் நமக்குள் நிலைத்திருக்கிறார்; அவருடைய அன்பும் நமக்குள் பூரணப்படும்.", "en": "No man hath seen God at any time. If we love one another, God dwelleth in us, and his love is perfected in us."}, {"verse": 13, "start": 149.59, "end": 159.07, "ta": "அவர் தம்முடைய ஆவியில் நமக்குத் தந்தருளினதினாலே நாம் அவரிலும் அவர் நம்மிலும் நிலைத்திருக்கிறதை அறிந்திருக்கிறோம்.", "en": "Hereby know we that we dwell in him, and he in us, because he hath given us of his Spirit."}, {"verse": 14, "start": 159.07, "end": 165.89, "ta": "பிதாவானவர் குமாரனை உலகரட்சகராக அனுப்பினாரென்று நாங்கள் கண்டு சாட்சியிடுகிறோம்.", "en": "And we have seen and do testify that the Father sent the Son to be the Saviour of the world."}, {"verse": 15, "start": 165.89, "end": 176.54, "ta": "இயேசுவானவர் தேவனுடைய குமாரனென்று அறிக்கைபண்ணுகிறவன் எவனோ அவனில் தேவன் நிலைத்திருக்கிறார், அவனும் தேவனில் நிலைத்திருக்கிறான்.", "en": "Whosoever shall confess that Jesus is the Son of God, God dwelleth in him, and he in God."}, {"verse": 16, "start": 176.54, "end": 193.39, "ta": "தேவன் நம்மேல் வைத்திருக்கிற அன்பை நாம் அறிந்து விசுவாசித்திருக்கிறோம். தேவன் அன்பாகவே இருக்கிறார்; அன்பில் நிலைத்திருக்கிறவன் தேவனில் நிலைத்திருக்கிறான், தேவனும் அவனில் நிலைத்திருக்கிறார்.", "en": "And we have known and believed the love that God hath to us. God is love; and he that dwelleth in love dwelleth in God, and God in him."}, {"verse": 17, "start": 193.39, "end": 207.41, "ta": "நியாயத்தீர்ப்புநாளிலே நமக்குத் தைரியமுண்டாயிருக்கத்தக்கதாக அன்பு நம்மிடத்தில் பூரணப்படுகிறது; ஏனென்றால், அவர் இருக்கிறபிரகாரமாக நாமும் இவ்வுலகத்தில் இருக்கிறோம்.", "en": "Herein is our love made perfect, that we may have boldness in the day of judgment: because as he is, so are we in this world."}, {"verse": 18, "start": 207.41, "end": 218.53, "ta": "அன்பிலே பயமில்லை; பூரண அன்பு பயத்தைப் புறம்பே தள்ளும்; பயமானது வேதனையுள்ளது, பயப்படுகிறவன் அன்பில் பூரணப்பட்டவன் அல்ல.", "en": "There is no fear in love; but perfect love casteth out fear: because fear hath torment. He that feareth is not made perfect in love."}, {"verse": 19, "start": 218.53, "end": 225.51, "ta": "அவர் முந்தி நம்மிடத்தில் அன்புகூர்ந்தபடியால் நாமும் அவரிடத்தில் அன்புகூருகிறோம்.", "en": "We love him, because he first loved us."}, {"verse": 20, "start": 225.51, "end": 241.88, "ta": "தேவனிடத்தில் அன்புகூருகிறேனென்று ஒருவன் சொல்லியும், தன் சகோதரனைப் பகைத்தால், அவன் பொய்யன்; தான் கண்ட சகோதரனிடத்தில் அன்புகூராமலிருக்கிறவன், தான் காணாத தேவனிடத்தில் எப்படி அன்புகூருவான்?", "en": "If a man say, I love God, and hateth his brother, he is a liar: for he that loveth not his brother whom he hath seen, how can he love God whom he hath not seen?"}, {"verse": 21, "start": 241.88, "end": 251.36, "ta": "தேவனிடத்தில் அன்புகூருகிறவன் தன் சகோதரனிடத்திலும் அன்புகூரவேண்டுமென்கிற இந்தக் கற்பனையை அவராலே பெற்றிருக்கிறோம்.", "en": "And this commandment have we from him, That he who loveth God love his brother also."}]}, "5": {"chapter": 5, "duration": 234.57, "audio_url": "audio_nt/B23_05.mp3", "total_verses": 21, "verses": [{"verse": 1, "start": 3.8, "end": 16.74, "ta": "இயேசுவானவரே கிறிஸ்து என்று விசுவாசிக்கிற எவனும் தேவனால் பிறந்திருக்கிறான்; பிறப்பித்தவரிடத்தில் அன்புகூருகிற எவனும் அவரால் பிறப்பிக்கப்பட்டவனிடத்திலும் அன்புகூருகிறான்.", "en": "Whosoever believeth that Jesus is the Christ is born of God: and every one that loveth him that begat loveth him also that is begotten of him."}, {"verse": 2, "start": 16.74, "end": 27.28, "ta": "நாம் தேவனிடத்தில் அன்புகூர்ந்து அவருடைய கற்பனைகளைக் கைக்கொள்ளும்போது, தேவனுடைய பிள்ளைகளிடத்தில் அன்புகூருகிறோமென்று அறிந்து கொள்ளுகிறோம்.", "en": "By this we know that we love the children of God, when we love God, and keep his commandments."}, {"verse": 3, "start": 27.28, "end": 35.41, "ta": "நாம் தேவனுடைய கற்பனைகளைக் கைக்கொள்வதே அவரிடத்தில் அன்புகூருவதாம்; அவருடைய கற்பனைகள் பாரமானவைகளுமல்ல.", "en": "For this is the love of God, that we keep his commandments: and his commandments are not grievous."}, {"verse": 4, "start": 35.41, "end": 42.55, "ta": "தேவனால் பிறப்பதெல்லாம் உலகத்தை ஜெயிக்கும்; நம்முடைய விசுவாசமே உலகத்தை ஜெயிக்கிற ஜெயம்.", "en": "For whatsoever is born of God overcometh the world: and this is the victory that overcometh the world, even our faith."}, {"verse": 5, "start": 42.55, "end": 48.92, "ta": "இயேசுவானவர் தேவனுடைய குமாரனென்று விசுவாசிக்கிறவனேயன்றி உலகத்தை ஜெயிக்கிறவன் யார்?", "en": "Who is he that overcometh the world, but he that believeth that Jesus is the Son of God?"}, {"verse": 6, "start": 48.92, "end": 63.7, "ta": "இயேசுகிறிஸ்துவாகிய இவரே ஜலத்தினாலும் இரத்தத்தினாலும் வந்தவர்; ஜலத்தினாலே மாத்திரமல்ல, ஜலத்தினாலும் இரத்தத்தினாலும் வந்தவர். ஆவியானவர் சத்தியமாகையால், ஆவியானவரே சாட்சிகொடுக்கிறவர்.", "en": "This is he that came by water and blood, even Jesus Christ; not by water only, but by water and blood. And it is the Spirit that beareth witness, because the Spirit is truth."}, {"verse": 7, "start": 63.7, "end": 72.96, "ta": "[பரலோகத்திலே சாட்சியிடுகிறவர்கள் மூவர், பிதா, வார்த்தை, பரிசுத்த ஆவி என்பவர்களே, இம்மூவரும் ஒன்றாயிருக்கிறார்கள்;", "en": "For there are three that bear record in heaven, the Father, the Word, and the Holy Ghost: and these three are one."}, {"verse": 8, "start": 72.96, "end": 81.8, "ta": "பூலோகத்திலே] சாட்சியிடுகிறவைகள் மூன்று, ஆவி, ஜலம், இரத்தம் என்பவைகளே, இம்மூன்றும் ஒருமைப்பட்டிருக்கிறது.", "en": "And there are three that bear witness in earth, the Spirit, and the water, and the blood: and these three agree in one."}, {"verse": 9, "start": 81.8, "end": 93.47, "ta": "நாம் மனுஷருடைய சாட்சியை ஏற்றுக்கொண்டால், அதைப்பார்க்கிலும் தேவனுடைய சாட்சி அதிகமாயிருக்கிறது; தேவன் தமது குமாரனைக் குறித்துக் கொடுத்த சாட்சி இதுவே.", "en": "If we receive the witness of men, the witness of God is greater: for this is the witness of God which he hath testified of his Son."}, {"verse": 10, "start": 93.47, "end": 109.6, "ta": "தேவனுடைய குமாரனிடத்தில் விசுவாசமாயிருக்கிறவன் அந்தச் சாட்சியைத் தனக்குள்ளே கொண்டிருக்கிறான்; தேவனை விசுவாசியாதவனோ, தேவன் தம்முடைய குமாரனைக் குறித்துக்கொடுத்த சாட்சியை விசுவாசியாததினால் அவரைப் பொய்யராக்குகிறான்.", "en": "He that believeth on the Son of God hath the witness in himself: he that believeth not God hath made him a liar; because he believeth not the record that God gave of his Son."}, {"verse": 11, "start": 109.6, "end": 118.08, "ta": "தேவன் நமக்கு நித்திய ஜீவனைத் தந்திருக்கிறார், அந்த ஜீவன் அவருடைய குமாரனில் இருக்கிறதென்பதே அந்தச்சாட்சியாம்.", "en": "And this is the record, that God hath given to us eternal life, and this life is in his Son."}, {"verse": 12, "start": 118.08, "end": 124.16, "ta": "குமாரனை உடையவன் ஜீவனை உடையவன், தேவனுடைய குமாரன் இல்லாதவன் ஜீவன் இல்லாதவன்.", "en": "He that hath the Son hath life; and he that hath not the Son of God hath not life."}, {"verse": 13, "start": 124.16, "end": 139.01, "ta": "உங்களுக்கு நித்தியஜீவன் உண்டென்று நீங்கள் அறியவும், தேவகுமாரனுடைய நாமத்தின் மேல் நீங்கள் விசுவாசமாயிருக்கவும், தேவகுமாரனுடைய நாமத்தின் மேல் விசுவாசமாயிருக்கிற உங்களுக்கு இவைகளை எழுதியிருக்கிறேன்.", "en": "These things have I written unto you that believe on the name of the Son of God; that ye may know that ye have eternal life, and that ye may believe on the name of the Son of God."}, {"verse": 14, "start": 139.01, "end": 148.7, "ta": "நாம் எதையாகிலும் அவருடைய சித்தத்தின்படிகேட்டால், அவர் நமக்குச் செவிகொடுக்கிறாரென்பதே அவரைப் பற்றி நாம் கொண்டிருக்கிற தைரியம்.", "en": "And this is the confidence that we have in him, that, if we ask any thing according to his will, he heareth us:"}, {"verse": 15, "start": 148.7, "end": 160.44, "ta": "நாம் எதைக் கேட்டாலும் அவர் நமக்குச் செவிகொடுக்கிறாரென்று நாம் அறிந்திருந்தோமானால், அவரிடத்தில் நாம் கேட்டவைகளைப் பெற்றுக்கொண்டோமென்றும் அறிந்திருக்கிறோம்.", "en": "And if we know that he hear us, whatsoever we ask, we know that we have the petitions that we desired of him."}, {"verse": 16, "start": 160.44, "end": 181.94, "ta": "மரணத்துக்கு ஏதுவல்லாத பாவத்தைத் தன் சகோதரன் செய்ய ஒருவன் கண்டால், அவன் வேண்டுதல்செய்யக்கடவன், அப்பொழுது அவனுக்கு ஜீவனைக் கொடுப்பார்; யாருக்கென்றால், மரணத்துக்கு ஏதுவல்லாத பாவத்தைச் செய்தவர்களுக்கே; மரணத்துக்கு ஏதுவான பாவமுண்டு, அதைக்குறித்து வேண்டுதல்செய்ய நான் சொல்லேன்.", "en": "If any man see his brother sin a sin which is not unto death, he shall ask, and he shall give him life for them that sin not unto death. There is a sin unto death: I do not say that he shall pray for it."}, {"verse": 17, "start": 181.94, "end": 187.88, "ta": "அநீதியெல்லாம் பாவந்தான்; என்றாலும் மரணத்துக்கு ஏதுவல்லாத பாவமுமுண்டு.", "en": "All unrighteousness is sin: and there is a sin not unto death."}, {"verse": 18, "start": 187.88, "end": 197.85, "ta": "தேவனால் பிறந்த எவனும் பாவஞ்செய்யானென்று அறிந்திருக்கிறோம்; தேவனால் பிறந்தவன் தன்னைக் காக்கிறான், பொல்லாங்கன் அவனைத் தொடான்.", "en": "We know that whosoever is born of God sinneth not; but he that is begotten of God keepeth himself, and that wicked one toucheth him not."}, {"verse": 19, "start": 197.85, "end": 206.06, "ta": "நாம் தேவனால் உண்டாயிருக்கிறோமென்றும், உலகமுழுவதும் பொல்லாங்கனுக்குள் கிடக்கிறதென்றும் அறிந்திருக்கிறோம்.", "en": "And we know that we are of God, and the whole world lieth in wickedness."}, {"verse": 20, "start": 206.06, "end": 225.64, "ta": "அன்றியும், நாம் சத்தியமுள்ளவரை அறிந்துகொள்வதற்கு தேவனுடைய குமாரன் வந்து நமக்குப் புத்தியைத் தந்திருக்கிறாரென்றும் அறிவோம்; அவருடைய குமாரனாகிய இயேசுகிறிஸ்து என்னப்பட்ட சத்தியமுள்ளவருக்குள்ளும் இருக்கிறோம்; இவரே மெய்யான தேவனும் நித்தியஜீவனுமாயிருக்கிறார்.", "en": "And we know that the Son of God is come, and hath given us an understanding, that we may know him that is true, and we are in him that is true, even in his Son Jesus Christ. This is the true God, and eternal life."}, {"verse": 21, "start": 225.64, "end": 233.07, "ta": "பிள்ளைகளே, நீங்கள் விக்கிரகங்களுக்கு விலகி, உங்களைக் காத்துக்கொள்வீர்களாக. ஆமென்.", "en": "Little children, keep yourselves from idols. Amen."}]}}});
} else {
  window.BIBLE_CACHE = window.BIBLE_CACHE || {};
  window.BIBLE_CACHE['62'] = {"id": 62, "testament": "NT", "code": "1JN", "name_en": "1 John", "name_ta": "1 யோவான்", "category": "General Epistles", "category_ta": "பொதுவான நிருபங்கள்", "total_chapters": 5, "chapters": {"1": {"chapter": 1, "duration": 128.01, "audio_url": "audio_nt/B23_01.mp3", "total_verses": 10, "verses": [{"verse": 1, "start": 4.8, "end": 21.1, "ta": "ஆதிமுதலாய் இருந்ததும், நாங்கள் கேட்டதும், எங்கள் கண்களினாலே கண்டதும், நாங்கள் நோக்கிப்பார்த்ததும், எங்கள் கைகளினாலே தொட்டுப்பார்த்ததுமாயிருக்கிற ஜீவவார்த்தையைக் குறித்து உங்களுக்கு அறிவிக்கிறோம்.", "en": "That which was from the beginning, which we have heard, which we have seen with our eyes, which we have looked upon, and our hands have handled, of the Word of life;"}, {"verse": 2, "start": 21.1, "end": 36.87, "ta": "அந்த ஜீவன் வெளிப்பட்டது; பிதாவினிடத்திலிருந்தும், எங்களுக்கு வெளிப்பட்டதுமான நித்தߠίமாயிருக்கிற அந்த ஜீவனை நாங்கள் கண்டு, அதைக்குறித்துச் சாட்சிக்கொடுத்து, அதை உங்களுக்கு அறிவிக்கிறோம்.", "en": "(For the life was manifested, and we have seen it , and bear witness, and shew unto you that eternal life, which was with the Father, and was manifested unto us;)"}, {"verse": 3, "start": 36.87, "end": 52.49, "ta": "நீங்களும் எங்களோடே ஐக்கியமுள்ளவர்களாகும்படி, நாங்கள் கண்டும் கேட்டும் இருக்கிறதை உங்களுக்கும் அறிவிக்கிறோம்; எங்களுடைய ஐக்கியம் பிதாவோடும் அவருடைய குமாரனாகிய இயேசுகிறிஸ்துவோடும் இருக்கிறது.", "en": "That which we have seen and heard declare we unto you, that ye also may have fellowship with us: and truly our fellowship is with the Father, and with his Son Jesus Christ."}, {"verse": 4, "start": 52.49, "end": 58.15, "ta": "உங்கள் சந்தோஷம் நிறைவாயிருக்கும்படி இவைகளை உங்களுக்கு எழுதுகிறேன்.", "en": "And these things write we unto you, that your joy may be full."}, {"verse": 5, "start": 58.15, "end": 69.39, "ta": "தேவன் ஒளியாயிருக்கிறார், அவரில் எவ்வளவேனும் இருளில்லை; இது நாங்கள் அவரிடத்தில் கேட்டு, உங்களுக்கு அறிவிக்கிற விசேஷமாயிருக்கிறது.", "en": "This then is the message which we have heard of him, and declare unto you, that God is light, and in him is no darkness at all."}, {"verse": 6, "start": 69.39, "end": 80.78, "ta": "நாம் அவரோடே ஐக்கியப்பட்டவர்கள் என்று சொல்லியும், இருளிலே நடக்கிறவர்களாயிருந்தால், சத்தியத்தின்படி நடவாமல் பொய்சொல்லுகிறவர்களாயிருப்போம்.", "en": "If we say that we have fellowship with him, and walk in darkness, we lie, and do not the truth:"}, {"verse": 7, "start": 80.78, "end": 95.72, "ta": "அவர் ஒளியிலிருக்கிறதுபோல நாமும் ஒளியிலே நடந்தால் ஒருவரோடொருவர் ஐக்கியப்பட்டிருப்போம்; அவருடைய குமாரனாகிய இயேசுகிறிஸ்துவின் இரத்தம் சகல பாவங்களையும் நீக்கி, நம்மைச் சுத்திகரிக்கும்.", "en": "But if we walk in the light, as he is in the light, we have fellowship one with another, and the blood of Jesus Christ his Son cleanseth us from all sin."}, {"verse": 8, "start": 95.72, "end": 103.72, "ta": "நமக்குப் பாவமில்லையென்போமானால் நம்மை நாமே வஞ்சிக்கிறவர்களாயிருப்போம், சத்தியம் நமக்குள் இராது.", "en": "If we say that we have no sin, we deceive ourselves, and the truth is not in us."}, {"verse": 9, "start": 103.72, "end": 117.0, "ta": "நம்முடைய பாவங்களை நாம் அறிக்கையிட்டால், பாவங்களை நமக்கு மன்னித்து எல்லா அநியாயத்தையும் நீக்கி நம்மைச் சுத்திகரிப்பதற்கு அவர் உண்மையும் நீதியும் உள்ளவராயிருக்கிறார்.", "en": "If we confess our sins, he is faithful and just to forgive us our sins, and to cleanse us from all unrighteousness."}, {"verse": 10, "start": 117.0, "end": 126.51, "ta": "நாம் பாவஞ்செய்யவில்லையென்போமானால், நாம் அவரைப் பொய்யராக்குகிறவர்களாயிருப்போம், அவருடைய வார்த்தை நமக்குள் இராது.", "en": "If we say that we have not sinned, we make him a liar, and his word is not in us."}]}, "2": {"chapter": 2, "duration": 373.6, "audio_url": "audio_nt/B23_02.mp3", "total_verses": 29, "verses": [{"verse": 1, "start": 3.8, "end": 20.14, "ta": "என் பிள்ளைகளே, நீங்கள் பாவஞ்செய்யாதபடிக்கு இவைகளை உங்களுக்கு எழுதுகிறேன்; ஒருவன் பாவஞ்செய்வானானால் நீதிபரராயிருக்கிற இயேசுகிறிஸ்து நமக்காகப் பிதாவினிடத்தில் பரிந்து பேசுகிறவராயிருக்கிறார்.", "en": "My little children, these things write I unto you, that ye sin not. And if any man sin, we have an advocate with the Father, Jesus Christ the righteous:"}, {"verse": 2, "start": 20.14, "end": 33.71, "ta": "நம்முடைய பாவங்களை நிவிர்த்தி செய்கிற கிருபாதாரபலி அவரே; நம்முடைய பாவங்களை மாத்திரம் அல்ல, சர்வலோகத்தின் பாவங்களையும் நிவிர்த்திசெய்கிற பலியாயிருக்கிறார்.", "en": "And he is the propitiation for our sins: and not for ours only, but also for the sins of the whole world."}, {"verse": 3, "start": 33.71, "end": 41.95, "ta": "அவருடைய கற்பனைகளை நாம் கைக்கொள்ளுகிறவர்களானால், அவரை அறிந்திருக்கிறோமென்பதை அதினால் அறிவோம்.", "en": "And hereby we do know that we know him, if we keep his commandments."}, {"verse": 4, "start": 41.95, "end": 52.58, "ta": "அவரை அறிந்திருக்கிறேனென்று சொல்லியும், அவருடைய கற்பனைகளைக் கைக்கொள்ளாதவன் பொய்யனாயிருக்கிறான், அவனுக்குள் சத்தியமில்லை.", "en": "He that saith, I know him, and keepeth not his commandments, is a liar, and the truth is not in him."}, {"verse": 5, "start": 52.58, "end": 65.04, "ta": "அவருடைய வசனத்தைக் கைக்கொள்ளுகிறவனிடத்தில் தேவ அன்பு மெய்யாகப் பூரணப்பட்டிருக்கும்; நாம் அவருக்குள் இருக்கிறோமென்பதை அதினாலே அறிந்திருக்கிறோம்.", "en": "But whoso keepeth his word, in him verily is the love of God perfected: hereby know we that we are in him."}, {"verse": 6, "start": 65.04, "end": 72.73, "ta": "அவருக்குள் நிலைத்திருக்கிறேனென்று சொல்லுகிறவன், அவர் நடந்தபடியே தானும் நடக்கவேண்டும்.", "en": "He that saith he abideth in him ought himself also so to walk, even as he walked."}, {"verse": 7, "start": 72.73, "end": 87.72, "ta": "சகோதரரே, நான் உங்களுக்குப் புதிய கற்பனையை அல்ல, ஆதிமுதல் நீங்கள் பெற்றிருக்கிற பழைய கற்பனையையே எழுதுகிறேன்; அந்தப் பழைய கற்பனை நீங்கள் ஆதிமுதல் கேட்டிருக்கிற வசனந்தானே.", "en": "Brethren, I write no new commandment unto you, but an old commandment which ye had from the beginning. The old commandment is the word which ye have heard from the beginning."}, {"verse": 8, "start": 87.72, "end": 104.3, "ta": "மேலும், நான் புதிய கற்பனையையும் உங்களுக்கு எழுதுகிறேன், இது அவருக்குள்ளும் உங்களுக்குள்ளும் மெய்யாயிருக்கிறது; ஏனென்றால், இருள் நீங்கிப்போகிறது, மெய்யான ஒளி இப்பொழுது பிரகாசிக்கிறது.", "en": "Again, a new commandment I write unto you, which thing is true in him and in you: because the darkness is past, and the true light now shineth."}, {"verse": 9, "start": 104.3, "end": 112.63, "ta": "ஒளியிலே இருக்கிறேன் என்று சொல்லியும் தன் சகோதரனைப் பகைக்கிறவன் இதுவரைக்கும் இருளிலே இருக்கிறான்.", "en": "He that saith he is in the light, and hateth his brother, is in darkness even until now."}, {"verse": 10, "start": 112.63, "end": 121.36, "ta": "தன் சகோதரனிடத்தில் அன்புகூருகிறவன் ஒளியிலே நிலைகொண்டிருக்கிறான்; அவனிடத்தில் இடறல் ஒன்றுமில்லை.", "en": "He that loveth his brother abideth in the light, and there is none occasion of stumbling in him."}, {"verse": 11, "start": 121.36, "end": 134.45, "ta": "தன் சகோதரனைப் பகைக்கிறவன் இருளிலே இருந்து இருளிலே நடக்கிறான்; இருளானது அவன் கண்களைக் குருடாக்கினபடியால் தான் போகும் இடம் இன்னதென்று அறியாதிருக்கிறான்.", "en": "But he that hateth his brother is in darkness, and walketh in darkness, and knoweth not whither he goeth, because that darkness hath blinded his eyes."}, {"verse": 12, "start": 134.45, "end": 143.65, "ta": "பிள்ளைகளே, அவருடைய நாமத்தினிமித்தம் உங்கள் பாவங்கள் மன்னிக்கப்பட்டிருக்கிறதினால் உங்களுக்கு எழுதுகிறேன்.", "en": "I write unto you, little children, because your sins are forgiven you for his name’s sake."}, {"verse": 13, "start": 143.65, "end": 162.05, "ta": "பிதாக்களே, ஆதிமுதலிருக்கிறவரை நீங்கள் அறிந்திருக்கிறதினால் உங்களுக்கு எழுதுகிறேன். வாலிபரே, ஜெயித்ததினால் உங்களுக்கு எழுதுகிறேன். பிள்ளைகளே நீங்கள் பிதாவை அறிந்திருக்கிறதினால் உங்களுக்கு எழுதுகிறேன்.", "en": "I write unto you, fathers, because ye have known him that is from the beginning. I write unto you, young men, because ye have overcome the wicked one. I write unto you, little children, because ye have known the Father."}, {"verse": 14, "start": 162.05, "end": 183.94, "ta": "பிதாக்களே, ஆதிமுதலிருக்கிறவரை நீங்கள் அறிந்திருக்கிறதினால் உங்களுக்கு எழுதியிருக்கிறேன். வாலிபரே, நீங்கள் பலவான்களாயிருக்கிறதினாலும், தேவவசனம் உங்களில் நிலைத்திருக்கிறதினாலும், நீங்கள் பொல்லாங்கனை ஜெயித்ததினாலும், உங்களுக்கு எழுதியிருக்கிறேன்.", "en": "I have written unto you, fathers, because ye have known him that is from the beginning. I have written unto you, young men, because ye are strong, and the word of God abideth in you, and ye have overcome the wicked one."}, {"verse": 15, "start": 183.94, "end": 194.49, "ta": "உலகத்திலும் உலகத்திலுள்ளவைகளிலும் அன்புகூராதிருங்கள்; ஒருவன் உலகத்தில் அன்புகூர்ந்தால் அவனிடத்தில் பிதாவின் அன்பில்லை.", "en": "Love not the world, neither the things that are in the world. If any man love the world, the love of the Father is not in him."}, {"verse": 16, "start": 194.49, "end": 208.38, "ta": "ஏனெனில், மாம்சத்தின் இச்சையும், கண்களின் இச்சையும், ஜீவனத்தின் பெருமையுமாகிய உலகத்திலுள்ளவைகளெல்லாம் பிதாவினாலுண்டானவைகளல்ல, அவைகள் உலகத்தினாலுண்டானவைகள்.", "en": "For all that is in the world, the lust of the flesh, and the lust of the eyes, and the pride of life, is not of the Father, but is of the world."}, {"verse": 17, "start": 208.38, "end": 217.89, "ta": "உலகமும் அதின் இச்சையும் ஒழிந்துபோம்; தேவனுடைய சித்தத்தின்படி செய்கிறவனோ என்றென்றைக்கும் நிலைத்திருப்பான்.", "en": "And the world passeth away, and the lust thereof: but he that doeth the will of God abideth for ever."}, {"verse": 18, "start": 217.89, "end": 234.47, "ta": "பிள்ளைகளே, இது கடைசிக்காலமாயிருக்கிறது; அந்திக்கிறிஸ்து வருகிறானென்று நீங்கள் கேள்விப்பட்டபடி இப்பொழுதும் அநேக அந்திக்கிறிஸ்துகள் இருக்கிறார்கள்; அதினாலே இது கடைசிக்காலமென்று அறிகிறோம்.", "en": "Little children, it is the last time: and as ye have heard that antichrist shall come, even now are there many antichrists; whereby we know that it is the last time."}, {"verse": 19, "start": 234.47, "end": 253.67, "ta": "அவர்கள் நம்மைவிட்டுப் பிரிந்து போனார்கள், ஆகிலும் அவர்கள் நம்முடையவர்களாயிருக்கவில்லை; நம்முடையவர்களாயிருந்தார்களானால் நம்முடனே நிலைத்திருப்பார்களே; எல்லாரும் நம்முடையவர்களல்லவென்று வெளியாகும்படிக்கே பிரிந்துபோனார்கள்.", "en": "They went out from us, but they were not of us; for if they had been of us, they would no doubt have continued with us: but they went out , that they might be made manifest that they were not all of us."}, {"verse": 20, "start": 253.67, "end": 260.09, "ta": "நீங்கள் பரிசுத்தராலே அபிஷேகம் பெற்றுச் சகலத்தையும் அறிந்திருக்கிறீர்கள்.", "en": "But ye have an unction from the Holy One, and ye know all things."}, {"verse": 21, "start": 260.09, "end": 275.64, "ta": "சத்தியத்தை நீங்கள் அறியாததினாலல்ல, நீங்கள் சத்தியத்தை அறிந்திருக்கிறதினாலும் சத்தியத்தினால் ஒரு பொய்யுமுண்டாயிராதென்பதை நீங்கள் அறிந்திருக்கிறதினாலும், உங்களுக்கு எழுதியிருக்கிறேன்.", "en": "I have not written unto you because ye know not the truth, but because ye know it, and that no lie is of the truth."}, {"verse": 22, "start": 275.64, "end": 287.06, "ta": "இயேசுவைக் கிறிஸ்து அல்ல என்று மறுதலிக்கிறவனேயல்லாமல் வேறே யார் பொய்யன்? பிதாவையும் குமாரனையும் மறுதலிக்கிறவனே அந்திக்கிறிஸ்து.", "en": "Who is a liar but he that denieth that Jesus is the Christ? He is antichrist, that denieth the Father and the Son."}, {"verse": 23, "start": 287.06, "end": 295.79, "ta": "குமாரனை மறுதலிக்கிறவன் பிதாவை உடையவனல்ல, குமாரனை அறிக்கையிடுகிறவன் பிதாவையும் உடையவனாயிருக்கிறான்.", "en": "Whosoever denieth the Son, the same hath not the Father: (but) he that acknowledgeth the Son hath the Father also ."}, {"verse": 24, "start": 295.79, "end": 311.73, "ta": "ஆகையால் ஆதிமுதல் நீங்கள் கேள்விப்பட்டது உங்களில் நிலைத்திருக்கக்கடவது; ஆதிமுதல் நீங்கள் கேள்விப்பட்டது உங்களில் நிலைத்திருந்தால், நீங்களும் குமாரனிலும் பிதாவிலும் நிலைத்திருப்பீர்கள்.", "en": "Let that therefore abide in you, which ye have heard from the beginning. If that which ye have heard from the beginning shall remain in you, ye also shall continue in the Son, and in the Father."}, {"verse": 25, "start": 311.73, "end": 317.68, "ta": "நித்திய ஜீவனை அளிப்பேன் என்பதே அவர் நமக்குச் செய்த வாக்குத்தத்தம்.", "en": "And this is the promise that he hath promised us, even eternal life."}, {"verse": 26, "start": 317.68, "end": 324.03, "ta": "உங்களை வஞ்சிக்கிறவர்களைக் குறித்து இவைகளை உங்களுக்கு எழுதியிருக்கிறேன்.", "en": "These things have I written unto you concerning them that seduce you."}, {"verse": 27, "start": 324.03, "end": 346.64, "ta": "நீங்கள் அவராலே பெற்ற அபிஷேகம் உங்களில் நிலைத்திருக்கிறது, ஒருவரும் உங்களுக்குப் போதிக்கவேண்டுவதில்லை; அந்த அபிஷேகம் சகலத்தையுங்குறித்து உங்களுக்குப் போதிக்கிறது; அது சத்தியமாயிருக்கிறது, பொய்யல்ல, அது உங்களுக்குப் போதித்தபடியே அவரில் நிலைத்திருப்பீர்களாக.", "en": "But the anointing which ye have received of him abideth in you, and ye need not that any man teach you: but as the same anointing teacheth you of all things, and is truth, and is no lie, and even as it hath taught you, ye shall abide in him."}, {"verse": 28, "start": 346.64, "end": 360.44, "ta": "இப்படியிருக்க, பிள்ளைகளே, அவர் வெளிப்படும்போது நாம் அவர் வருகையில் அவருக்கு முன்பாக வெட்கப்பட்டுப்போகாமல் தைரியமுள்ளவர்களாயிருக்கும்படி அவரில் நிலைத்திருங்கள்.", "en": "And now, little children, abide in him; that, when he shall appear, we may have confidence, and not be ashamed before him at his coming."}, {"verse": 29, "start": 360.44, "end": 372.1, "ta": "அவர் நீதியுள்ளவராயிருக்கிறாரென்று உங்களுக்குத் தெரிந்திருப்பதினால், நீதியைச் செய்கிறவனெவனும் அவரில் பிறந்தவனென்று அறிந்திருக்கிறீர்கள்.", "en": "If ye know that he is righteous, ye know that every one that doeth righteousness is born of him."}]}, "3": {"chapter": 3, "duration": 277.56, "audio_url": "audio_nt/B23_03.mp3", "total_verses": 24, "verses": [{"verse": 1, "start": 3.8, "end": 16.69, "ta": "நாம் தேவனுடைய பிள்ளைகளென்று அழைக்கப்படுவதினாலே பிதாவானவர் நமக்குப் பாராட்டின அன்பு எவ்வளவு பெரிதென்று பாருங்கள்; உலகம் அவரை அறியாதபடியினாலே நம்மையும் அறியவில்லை.", "en": "Behold, what manner of love the Father hath bestowed upon us, that we should be called the sons of God: therefore the world knoweth us not, because it knew him not."}, {"verse": 2, "start": 16.69, "end": 35.73, "ta": "பிரியமானவர்களே, இப்பொழுது தேவனுடைய பிள்ளைகளாயிருக்கிறோம், இனி எவ்விதமாயிருப்போமென்று இன்னும் வெளிப்படவில்லை; ஆகிலும் அவர் வெளிப்படும்போது அவர் இருக்கிறவண்ணமாகவே நாம் அவரைத் தரிசிப்பதினால், அவருக்கு ஒப்பாயிருப்போமென்று அறிந்திருக்கிறோம்.", "en": "Beloved, now are we the sons of God, and it doth not yet appear what we shall be: but we know that, when he shall appear, we shall be like him; for we shall see him as he is."}, {"verse": 3, "start": 35.73, "end": 46.13, "ta": "அவர்மேல் இப்படிப்பட்ட நம்பிக்கை வைத்திருக்கிறவனெவனும், அவர் சுத்தமுள்ளவராயிருக்கிறதுபோல, தன்னையும் சுத்திகரித்துக்கொள்ளுகிறான்.", "en": "And every man that hath this hope in him purifieth himself, even as he is pure."}, {"verse": 4, "start": 46.13, "end": 53.38, "ta": "பாவஞ்செய்கிற எவனும் நியாயப்பிரமாணத்தை மீறுகிறான்; நியாயப்பிரமாணத்தை மீறுகிறதே பாவம்.", "en": "Whosoever committeth sin transgresseth also the law: for sin is the transgression of the law."}, {"verse": 5, "start": 53.38, "end": 61.28, "ta": "அவர் நம்முடைய பாவங்களைச் சுமந்து தீர்க்க வெளிப்பட்டாரென்று அறிவீர்கள்; அவரிடத்தில் பாவமில்லை.", "en": "And ye know that he was manifested to take away our sins; and in him is no sin."}, {"verse": 6, "start": 61.28, "end": 69.78, "ta": "அவரில் நிலைத்திருக்கிற எவனும் பாவஞ்செய்கிறதில்லை; பாவஞ்செய்கிற எவனும் அவரைக் காணவுமில்லை, அவரை அறியவுமில்லை", "en": "Whosoever abideth in him sinneth not: whosoever sinneth hath not seen him, neither known him."}, {"verse": 7, "start": 69.78, "end": 81.06, "ta": "பிள்ளைகளே நீங்கள் ஒருவராலும் வஞ்சிக்கப்படாதிருங்கள்; நீதியைச் செய்கிறவன் அவர் நீதியுள்ளவராயிருக்கிறதுபோலத் தானும் நீதியுள்ளவனாயிருக்கிறான்.", "en": "Little children, let no man deceive you: he that doeth righteousness is righteous, even as he is righteous."}, {"verse": 8, "start": 81.06, "end": 94.02, "ta": "பாவஞ்செய்கிறவன் பிசாசினாலுண்டாயிருக்கிறான்; ஏனெனில் பிசாசானவன் ஆதிமுதல் பாவஞ்செய்கிறான், பிசாசினுடைய கிரியைகளை அழிக்கும்படிக்கே தேவனுடைய குமாரன் வெளிப்பட்டார்.", "en": "He that committeth sin is of the devil; for the devil sinneth from the beginning. For this purpose the Son of God was manifested, that he might destroy the works of the devil."}, {"verse": 9, "start": 94.02, "end": 105.37, "ta": "தேவனால் பிறந்த எவனும் பாவஞ்செய்யான், ஏனெனில் அவருடைய வித்து அவனுக்குள் தரித்திருக்கிறது; அவன் தேவனால் பிறந்தபடியினால் பாவஞ்செய்யமாட்டான்.", "en": "Whosoever is born of God doth not commit sin; for his seed remaineth in him: and he cannot sin, because he is born of God."}, {"verse": 10, "start": 105.37, "end": 119.21, "ta": "இதினாலே தேவனுடைய பிள்ளைகள் இன்னாரென்றும், பிசாசின் பிள்ளைகள் இன்னாரென்றும் வெளிப்படும்; நீதியைச்செய்யாமலும் தன் சகோதரனில் அன்புகூராமலும் இருக்கிற எவனும் தேவனாலுண்டானவனல்ல.", "en": "In this the children of God are manifest, and the children of the devil: whosoever doeth not righteousness is not of God, neither he that loveth not his brother."}, {"verse": 11, "start": 119.21, "end": 126.46, "ta": "நாம் ஒருவரிலொருவர் அன்புகூரவேண்டுமென்பதே நீங்கள் ஆதிமுதல் கேள்விப்பட்ட விசேஷமாயிருக்கிறது.", "en": "For this is the message that ye heard from the beginning, that we should love one another."}, {"verse": 12, "start": 126.46, "end": 143.96, "ta": "பொல்லாங்கனால் உண்டாயிருந்து தன் சகோதரனைக் கொலைசெய்த காயீனைப்போலிருக்கவேண்டாம்; அவன் எதினிமித்தம் அவனைக் கொலைசெய்தான்? தன் கிரியைகள் பொல்லாதவைகளும், தன் சகோதரனுடைய கிரியைகள் நீதியுள்ளவைகளுமாயிருந்ததினிமித்தந்தானே.", "en": "Not as Cain, who was of that wicked one, and slew his brother. And wherefore slew he him? Because his own works were evil, and his brother’s righteous."}, {"verse": 13, "start": 143.96, "end": 149.23, "ta": "என் சகோதரரே, உலகம் உங்களைப் பகைத்தால் ஆச்சரியப்படாதிருங்கள்.", "en": "Marvel not, my brethren, if the world hate you."}, {"verse": 14, "start": 149.23, "end": 163.36, "ta": "நாம் சகோதரரிடத்தில் அன்புகூருகிறபடியால், மரணத்தைவிட்டு நீங்கி ஜீவனுக்குட்பட்டிருக்கிறோமென்று அறிந்திருக்கிறோம். சகோதரனிடத்தில் அன்புகூராதவன் மரணத்தில் நிலைகொண்டிருக்கிறான்.", "en": "We know that we have passed from death unto life, because we love the brethren. He that loveth not his brother abideth in death."}, {"verse": 15, "start": 163.36, "end": 174.05, "ta": "தன் சகோதரனைப் பகைக்கிற எவனும் மனுஷகொலைபாதகனாயிருக்கிறான்; மனுஷ கொலைபாதகனெவனோ அவனுக்குள் நித்தியஜீவன் நிலைத்திராது என்று அறிவீர்கள்.", "en": "Whosoever hateth his brother is a murderer: and ye know that no murderer hath eternal life abiding in him."}, {"verse": 16, "start": 174.05, "end": 185.33, "ta": "அவர் தம்முடைய ஜீவனை நமக்காகக் கொடுத்ததினாலே அன்பு இன்னதென்று அறிந்திருக்கிறோம்; நாமும் சகோதரருக்காக ஜீவனைக்கொடுக்கக் கடனாளிகளாயிருக்கிறோம்.", "en": "Hereby perceive we the love of God , because he laid down his life for us: and we ought to lay down our lives for the brethren."}, {"verse": 17, "start": 185.33, "end": 198.73, "ta": "ஒருவன் இவ்வுலக ஆஸ்தி உடையவனாயிருந்து, தன் சகோதரனுக்குக் குறைச்சலுண்டென்று கண்டு, தன் இருதயத்தை அவனுக்கு அடைத்துக்கொண்டால், அவனுக்குள் தேவ அன்பு நிலைகொள்ளுகிறதெப்படி?", "en": "But whoso hath this world’s good, and seeth his brother have need, and shutteth up his bowels of compassion from him, how dwelleth the love of God in him?"}, {"verse": 18, "start": 198.73, "end": 206.64, "ta": "என் பிள்ளைகளே, வசனத்தினாலும், நாவினாலுமல்ல, கிரியையினாலும் உண்மையினாலும் அன்புகூரக்கடவோம்.", "en": "My little children, let us not love in word, neither in tongue; but in deed and in truth."}, {"verse": 19, "start": 206.64, "end": 216.38, "ta": "இதினாலே நாம் நம்மைச் சத்தியத்திற்குரியவர்களென்று அறிந்து, நம்முடைய இருதயத்தை அவருக்கு முன்பாக நிச்சயப்படுத்திக்கொள்ளலாம்.", "en": "And hereby we know that we are of the truth, and shall assure our hearts before him."}, {"verse": 20, "start": 216.38, "end": 227.0, "ta": "நம்முடைய இருதயமே நம்மைக் குற்றவாளிகளாகத் தீர்க்குமானால், தேவன் நம்முடைய இருதயத்திலும் பெரியவராயிருந்து சகலத்தையும் அறிந்திருக்கிறார்.", "en": "For if our heart condemn us, God is greater than our heart, and knoweth all things."}, {"verse": 21, "start": 227.0, "end": 236.15, "ta": "பிரியமானவர்களே, நம்முடைய இருதயம் நம்மைக் குற்றவாளிகளென்று தீர்க்காதிருந்தால், நாம் தேவனிடத்தில் தைரியங்கொண்டிருந்து,", "en": "Beloved, if our heart condemn us not, then have we confidence toward God."}, {"verse": 22, "start": 236.15, "end": 247.57, "ta": "அவருடைய கற்பனைகளை நாம் கைக்கொண்டு அவருக்கு முன்பாகப் பிரியமானவைகளைச் செய்கிறபடியினால் நாம் வேண்டிக்கொள்ளுகிறதெதுவோ அதை அவராலே பெற்றுக்கொள்ளுகிறோம்.", "en": "And whatsoever we ask, we receive of him, because we keep his commandments, and do those things that are pleasing in his sight."}, {"verse": 23, "start": 247.57, "end": 261.05, "ta": "நாம் அவருடைய குமாரனாகிய இயேசுகிறிஸ்துவின் நாமத்தின்மேல் விசுவாசமாயிருந்து, அவர் நமக்குக் கட்டளையிட்டபடி ஒருவரிலொருவர் அன்பாயிருக்கவேண்டுமென்பதே அவருடைய கற்பனையாயிருக்கிறது.", "en": "And this is his commandment, That we should believe on the name of his Son Jesus Christ, and love one another, as he gave us commandment."}, {"verse": 24, "start": 261.05, "end": 276.06, "ta": "அவருடைய கட்டளைகளைக் கைக்கொள்ளுகிறவன் அவரில் நிலைத்திருக்கிறான். அவரும் அவனில் நிலைத்திருக்கிறார்; அவர் நம்மில் நிலைத்திருக்கிறதை அவர் நமக்குத் தந்தருளின ஆவியினாலே அறிந்திருக்கிறோம்.", "en": "And he that keepeth his commandments dwelleth in him, and he in him. And hereby we know that he abideth in us, by the Spirit which he hath given us."}]}, "4": {"chapter": 4, "duration": 252.86, "audio_url": "audio_nt/B23_04.mp3", "total_verses": 21, "verses": [{"verse": 1, "start": 3.8, "end": 15.79, "ta": "அநேகங் கள்ளத்தீர்க்கதரிசிகள் தோன்றியிருப்பதினால், நீங்கள் எல்லா ஆவிகளையும் நம்பாமல், அந்த ஆவிகள் தேவனாலுண்டானவைகளோ என்று சோதித்தறியுங்கள்.", "en": "Beloved, believe not every spirit, but try the spirits whether they are of God: because many false prophets are gone out into the world."}, {"verse": 2, "start": 15.79, "end": 26.52, "ta": "தேவஆவியை நீங்கள் எதினாலே அறியலாமென்றால்: மாம்சத்தில் வந்த இயேசுகிறிஸ்துவை அறிக்கைபண்ணுகிற எந்த ஆவியும் தேவனால் உண்டாயிருக்கிறது.", "en": "Hereby know ye the Spirit of God: Every spirit that confesseth that Jesus Christ is come in the flesh is of God:"}, {"verse": 3, "start": 26.52, "end": 42.19, "ta": "மாம்சத்தில் வந்த இயேசுகிறிஸ்துவை அறிக்கைபண்ணாத எந்த ஆவியும் தேவனால் உண்டானதல்ல; வருமென்று நீங்கள் கேள்விப்பட்ட அந்திக்கிறிஸ்துவினுடைய ஆவி அதுவே, அது இப்பொழுதும் உலகத்தில் இருக்கிறது.", "en": "And every spirit that confesseth not that Jesus Christ is come in the flesh is not of God: and this is that spirit of antichrist, whereof ye have heard that it should come; and even now already is it in the world."}, {"verse": 4, "start": 42.19, "end": 53.47, "ta": "பிள்ளைகளே, நீங்கள் தேவனாலுண்டாயிருந்து, அவர்களை ஜெயித்தீர்கள்; ஏனெனில் உலகத்திலிருக்கிறவனிலும் உங்களிலிருக்கிறவர் பெரியவர்.", "en": "Ye are of God, little children, and have overcome them: because greater is he that is in you, than he that is in the world."}, {"verse": 5, "start": 53.47, "end": 63.42, "ta": "அவர்கள் உலகத்துக்குரியவர்கள், ஆகையால் உலகத்துக்குரியவைகளைப் பேசுகிறார்கள், உலகமும் அவர்களுக்குச் செவிகொடுக்கும்.", "en": "They are of the world: therefore speak they of the world, and the world heareth them."}, {"verse": 6, "start": 63.42, "end": 81.91, "ta": "நாங்கள் தேவனால் உண்டானவர்கள்; தேவனை அறிந்தவன் எங்களுக்குச் செவிகொடுக்கிறான்; தேவனால் உண்டாயிராதவன் எங்களுக்குச் செவிகொடுக்கிறதில்லை; இதினாலே சத்திய ஆவி இன்னதென்றும், வஞ்சகஆவி இன்னதென்றும் அறிந்திருக்கிறோம்.", "en": "We are of God: he that knoweth God heareth us; he that is not of God heareth not us. Hereby know we the spirit of truth, and the spirit of error."}, {"verse": 7, "start": 81.91, "end": 93.03, "ta": "அன்பாயிருக்கக்கடவோம்; ஏனெனில் அன்பு தேவனால் உண்டாயிருக்கிறது; அன்புள்ள எவனும் தேவனால் பிறந்து, அவரை அறிந்திருக்கிறான்.", "en": "Beloved, let us love one another: for love is of God; and every one that loveth is born of God, and knoweth God."}, {"verse": 8, "start": 93.03, "end": 98.36, "ta": "அன்பில்லாதவன் தேவனை அறியான், தேவன் அன்பாகவே இருக்கிறார்.", "en": "He that loveth not knoweth not God; for God is love."}, {"verse": 9, "start": 98.36, "end": 109.33, "ta": "தம்முடைய ஒரே பேறான குமாரனாலே நாம் பிழைக்கும்படிக்கு தேவன் அவரை இவ்வுலகத்திலே அனுப்பினதினால் தேவன் நம்மேல் வைத்த அன்பு வெளிப்பட்டது.", "en": "In this was manifested the love of God toward us, because that God sent his only begotten Son into the world, that we might live through him."}, {"verse": 10, "start": 109.33, "end": 124.99, "ta": "நாம் தேவனிடத்தில் அன்புகூர்ந்ததினால் அல்ல, அவர் நம்மிடத்தில் அன்புகூர்ந்து, நம்முடைய பாவங்களை நிவிர்த்திசெய்கிற கிருபாதாரபலியாகத் தம்முடைய குமாரனை அனுப்பினதினாலே அன்பு உண்டாயிருக்கிறது.", "en": "Herein is love, not that we loved God, but that he loved us, and sent his Son to be the propitiation for our sins."}, {"verse": 11, "start": 124.99, "end": 136.12, "ta": "பிரியமானவர்களே, தேவன் இவ்விதமாய் நம்மிடத்தில் அன்புகூர்ந்திருக்க, நாமும் ஒருவரிடத்தில் ஒருவர் அன்புகூரக் கடனாளிகளாயிருக்கிறோம்.", "en": "Beloved, if God so loved us, we ought also to love one another."}, {"verse": 12, "start": 136.12, "end": 149.59, "ta": "தேவனை ஒருவரும் ஒருபோதும் கண்டதில்லை; நாம் ஒருவரிடத்தில் ஒருவர் அன்புகூர்ந்தால் தேவன் நமக்குள் நிலைத்திருக்கிறார்; அவருடைய அன்பும் நமக்குள் பூரணப்படும்.", "en": "No man hath seen God at any time. If we love one another, God dwelleth in us, and his love is perfected in us."}, {"verse": 13, "start": 149.59, "end": 159.07, "ta": "அவர் தம்முடைய ஆவியில் நமக்குத் தந்தருளினதினாலே நாம் அவரிலும் அவர் நம்மிலும் நிலைத்திருக்கிறதை அறிந்திருக்கிறோம்.", "en": "Hereby know we that we dwell in him, and he in us, because he hath given us of his Spirit."}, {"verse": 14, "start": 159.07, "end": 165.89, "ta": "பிதாவானவர் குமாரனை உலகரட்சகராக அனுப்பினாரென்று நாங்கள் கண்டு சாட்சியிடுகிறோம்.", "en": "And we have seen and do testify that the Father sent the Son to be the Saviour of the world."}, {"verse": 15, "start": 165.89, "end": 176.54, "ta": "இயேசுவானவர் தேவனுடைய குமாரனென்று அறிக்கைபண்ணுகிறவன் எவனோ அவனில் தேவன் நிலைத்திருக்கிறார், அவனும் தேவனில் நிலைத்திருக்கிறான்.", "en": "Whosoever shall confess that Jesus is the Son of God, God dwelleth in him, and he in God."}, {"verse": 16, "start": 176.54, "end": 193.39, "ta": "தேவன் நம்மேல் வைத்திருக்கிற அன்பை நாம் அறிந்து விசுவாசித்திருக்கிறோம். தேவன் அன்பாகவே இருக்கிறார்; அன்பில் நிலைத்திருக்கிறவன் தேவனில் நிலைத்திருக்கிறான், தேவனும் அவனில் நிலைத்திருக்கிறார்.", "en": "And we have known and believed the love that God hath to us. God is love; and he that dwelleth in love dwelleth in God, and God in him."}, {"verse": 17, "start": 193.39, "end": 207.41, "ta": "நியாயத்தீர்ப்புநாளிலே நமக்குத் தைரியமுண்டாயிருக்கத்தக்கதாக அன்பு நம்மிடத்தில் பூரணப்படுகிறது; ஏனென்றால், அவர் இருக்கிறபிரகாரமாக நாமும் இவ்வுலகத்தில் இருக்கிறோம்.", "en": "Herein is our love made perfect, that we may have boldness in the day of judgment: because as he is, so are we in this world."}, {"verse": 18, "start": 207.41, "end": 218.53, "ta": "அன்பிலே பயமில்லை; பூரண அன்பு பயத்தைப் புறம்பே தள்ளும்; பயமானது வேதனையுள்ளது, பயப்படுகிறவன் அன்பில் பூரணப்பட்டவன் அல்ல.", "en": "There is no fear in love; but perfect love casteth out fear: because fear hath torment. He that feareth is not made perfect in love."}, {"verse": 19, "start": 218.53, "end": 225.51, "ta": "அவர் முந்தி நம்மிடத்தில் அன்புகூர்ந்தபடியால் நாமும் அவரிடத்தில் அன்புகூருகிறோம்.", "en": "We love him, because he first loved us."}, {"verse": 20, "start": 225.51, "end": 241.88, "ta": "தேவனிடத்தில் அன்புகூருகிறேனென்று ஒருவன் சொல்லியும், தன் சகோதரனைப் பகைத்தால், அவன் பொய்யன்; தான் கண்ட சகோதரனிடத்தில் அன்புகூராமலிருக்கிறவன், தான் காணாத தேவனிடத்தில் எப்படி அன்புகூருவான்?", "en": "If a man say, I love God, and hateth his brother, he is a liar: for he that loveth not his brother whom he hath seen, how can he love God whom he hath not seen?"}, {"verse": 21, "start": 241.88, "end": 251.36, "ta": "தேவனிடத்தில் அன்புகூருகிறவன் தன் சகோதரனிடத்திலும் அன்புகூரவேண்டுமென்கிற இந்தக் கற்பனையை அவராலே பெற்றிருக்கிறோம்.", "en": "And this commandment have we from him, That he who loveth God love his brother also."}]}, "5": {"chapter": 5, "duration": 234.57, "audio_url": "audio_nt/B23_05.mp3", "total_verses": 21, "verses": [{"verse": 1, "start": 3.8, "end": 16.74, "ta": "இயேசுவானவரே கிறிஸ்து என்று விசுவாசிக்கிற எவனும் தேவனால் பிறந்திருக்கிறான்; பிறப்பித்தவரிடத்தில் அன்புகூருகிற எவனும் அவரால் பிறப்பிக்கப்பட்டவனிடத்திலும் அன்புகூருகிறான்.", "en": "Whosoever believeth that Jesus is the Christ is born of God: and every one that loveth him that begat loveth him also that is begotten of him."}, {"verse": 2, "start": 16.74, "end": 27.28, "ta": "நாம் தேவனிடத்தில் அன்புகூர்ந்து அவருடைய கற்பனைகளைக் கைக்கொள்ளும்போது, தேவனுடைய பிள்ளைகளிடத்தில் அன்புகூருகிறோமென்று அறிந்து கொள்ளுகிறோம்.", "en": "By this we know that we love the children of God, when we love God, and keep his commandments."}, {"verse": 3, "start": 27.28, "end": 35.41, "ta": "நாம் தேவனுடைய கற்பனைகளைக் கைக்கொள்வதே அவரிடத்தில் அன்புகூருவதாம்; அவருடைய கற்பனைகள் பாரமானவைகளுமல்ல.", "en": "For this is the love of God, that we keep his commandments: and his commandments are not grievous."}, {"verse": 4, "start": 35.41, "end": 42.55, "ta": "தேவனால் பிறப்பதெல்லாம் உலகத்தை ஜெயிக்கும்; நம்முடைய விசுவாசமே உலகத்தை ஜெயிக்கிற ஜெயம்.", "en": "For whatsoever is born of God overcometh the world: and this is the victory that overcometh the world, even our faith."}, {"verse": 5, "start": 42.55, "end": 48.92, "ta": "இயேசுவானவர் தேவனுடைய குமாரனென்று விசுவாசிக்கிறவனேயன்றி உலகத்தை ஜெயிக்கிறவன் யார்?", "en": "Who is he that overcometh the world, but he that believeth that Jesus is the Son of God?"}, {"verse": 6, "start": 48.92, "end": 63.7, "ta": "இயேசுகிறிஸ்துவாகிய இவரே ஜலத்தினாலும் இரத்தத்தினாலும் வந்தவர்; ஜலத்தினாலே மாத்திரமல்ல, ஜலத்தினாலும் இரத்தத்தினாலும் வந்தவர். ஆவியானவர் சத்தியமாகையால், ஆவியானவரே சாட்சிகொடுக்கிறவர்.", "en": "This is he that came by water and blood, even Jesus Christ; not by water only, but by water and blood. And it is the Spirit that beareth witness, because the Spirit is truth."}, {"verse": 7, "start": 63.7, "end": 72.96, "ta": "[பரலோகத்திலே சாட்சியிடுகிறவர்கள் மூவர், பிதா, வார்த்தை, பரிசுத்த ஆவி என்பவர்களே, இம்மூவரும் ஒன்றாயிருக்கிறார்கள்;", "en": "For there are three that bear record in heaven, the Father, the Word, and the Holy Ghost: and these three are one."}, {"verse": 8, "start": 72.96, "end": 81.8, "ta": "பூலோகத்திலே] சாட்சியிடுகிறவைகள் மூன்று, ஆவி, ஜலம், இரத்தம் என்பவைகளே, இம்மூன்றும் ஒருமைப்பட்டிருக்கிறது.", "en": "And there are three that bear witness in earth, the Spirit, and the water, and the blood: and these three agree in one."}, {"verse": 9, "start": 81.8, "end": 93.47, "ta": "நாம் மனுஷருடைய சாட்சியை ஏற்றுக்கொண்டால், அதைப்பார்க்கிலும் தேவனுடைய சாட்சி அதிகமாயிருக்கிறது; தேவன் தமது குமாரனைக் குறித்துக் கொடுத்த சாட்சி இதுவே.", "en": "If we receive the witness of men, the witness of God is greater: for this is the witness of God which he hath testified of his Son."}, {"verse": 10, "start": 93.47, "end": 109.6, "ta": "தேவனுடைய குமாரனிடத்தில் விசுவாசமாயிருக்கிறவன் அந்தச் சாட்சியைத் தனக்குள்ளே கொண்டிருக்கிறான்; தேவனை விசுவாசியாதவனோ, தேவன் தம்முடைய குமாரனைக் குறித்துக்கொடுத்த சாட்சியை விசுவாசியாததினால் அவரைப் பொய்யராக்குகிறான்.", "en": "He that believeth on the Son of God hath the witness in himself: he that believeth not God hath made him a liar; because he believeth not the record that God gave of his Son."}, {"verse": 11, "start": 109.6, "end": 118.08, "ta": "தேவன் நமக்கு நித்திய ஜீவனைத் தந்திருக்கிறார், அந்த ஜீவன் அவருடைய குமாரனில் இருக்கிறதென்பதே அந்தச்சாட்சியாம்.", "en": "And this is the record, that God hath given to us eternal life, and this life is in his Son."}, {"verse": 12, "start": 118.08, "end": 124.16, "ta": "குமாரனை உடையவன் ஜீவனை உடையவன், தேவனுடைய குமாரன் இல்லாதவன் ஜீவன் இல்லாதவன்.", "en": "He that hath the Son hath life; and he that hath not the Son of God hath not life."}, {"verse": 13, "start": 124.16, "end": 139.01, "ta": "உங்களுக்கு நித்தியஜீவன் உண்டென்று நீங்கள் அறியவும், தேவகுமாரனுடைய நாமத்தின் மேல் நீங்கள் விசுவாசமாயிருக்கவும், தேவகுமாரனுடைய நாமத்தின் மேல் விசுவாசமாயிருக்கிற உங்களுக்கு இவைகளை எழுதியிருக்கிறேன்.", "en": "These things have I written unto you that believe on the name of the Son of God; that ye may know that ye have eternal life, and that ye may believe on the name of the Son of God."}, {"verse": 14, "start": 139.01, "end": 148.7, "ta": "நாம் எதையாகிலும் அவருடைய சித்தத்தின்படிகேட்டால், அவர் நமக்குச் செவிகொடுக்கிறாரென்பதே அவரைப் பற்றி நாம் கொண்டிருக்கிற தைரியம்.", "en": "And this is the confidence that we have in him, that, if we ask any thing according to his will, he heareth us:"}, {"verse": 15, "start": 148.7, "end": 160.44, "ta": "நாம் எதைக் கேட்டாலும் அவர் நமக்குச் செவிகொடுக்கிறாரென்று நாம் அறிந்திருந்தோமானால், அவரிடத்தில் நாம் கேட்டவைகளைப் பெற்றுக்கொண்டோமென்றும் அறிந்திருக்கிறோம்.", "en": "And if we know that he hear us, whatsoever we ask, we know that we have the petitions that we desired of him."}, {"verse": 16, "start": 160.44, "end": 181.94, "ta": "மரணத்துக்கு ஏதுவல்லாத பாவத்தைத் தன் சகோதரன் செய்ய ஒருவன் கண்டால், அவன் வேண்டுதல்செய்யக்கடவன், அப்பொழுது அவனுக்கு ஜீவனைக் கொடுப்பார்; யாருக்கென்றால், மரணத்துக்கு ஏதுவல்லாத பாவத்தைச் செய்தவர்களுக்கே; மரணத்துக்கு ஏதுவான பாவமுண்டு, அதைக்குறித்து வேண்டுதல்செய்ய நான் சொல்லேன்.", "en": "If any man see his brother sin a sin which is not unto death, he shall ask, and he shall give him life for them that sin not unto death. There is a sin unto death: I do not say that he shall pray for it."}, {"verse": 17, "start": 181.94, "end": 187.88, "ta": "அநீதியெல்லாம் பாவந்தான்; என்றாலும் மரணத்துக்கு ஏதுவல்லாத பாவமுமுண்டு.", "en": "All unrighteousness is sin: and there is a sin not unto death."}, {"verse": 18, "start": 187.88, "end": 197.85, "ta": "தேவனால் பிறந்த எவனும் பாவஞ்செய்யானென்று அறிந்திருக்கிறோம்; தேவனால் பிறந்தவன் தன்னைக் காக்கிறான், பொல்லாங்கன் அவனைத் தொடான்.", "en": "We know that whosoever is born of God sinneth not; but he that is begotten of God keepeth himself, and that wicked one toucheth him not."}, {"verse": 19, "start": 197.85, "end": 206.06, "ta": "நாம் தேவனால் உண்டாயிருக்கிறோமென்றும், உலகமுழுவதும் பொல்லாங்கனுக்குள் கிடக்கிறதென்றும் அறிந்திருக்கிறோம்.", "en": "And we know that we are of God, and the whole world lieth in wickedness."}, {"verse": 20, "start": 206.06, "end": 225.64, "ta": "அன்றியும், நாம் சத்தியமுள்ளவரை அறிந்துகொள்வதற்கு தேவனுடைய குமாரன் வந்து நமக்குப் புத்தியைத் தந்திருக்கிறாரென்றும் அறிவோம்; அவருடைய குமாரனாகிய இயேசுகிறிஸ்து என்னப்பட்ட சத்தியமுள்ளவருக்குள்ளும் இருக்கிறோம்; இவரே மெய்யான தேவனும் நித்தியஜீவனுமாயிருக்கிறார்.", "en": "And we know that the Son of God is come, and hath given us an understanding, that we may know him that is true, and we are in him that is true, even in his Son Jesus Christ. This is the true God, and eternal life."}, {"verse": 21, "start": 225.64, "end": 233.07, "ta": "பிள்ளைகளே, நீங்கள் விக்கிரகங்களுக்கு விலகி, உங்களைக் காத்துக்கொள்வீர்களாக. ஆமென்.", "en": "Little children, keep yourselves from idols. Amen."}]}}};
}
